import{_ as a,o as e,c as o,a2 as i}from"./chunks/framework.A5mep7Fe.js";const _=JSON.parse('{"title":"🌫️ 01 · 扩散模型 Diffusion（⭐ 必考）","description":"","frontmatter":{},"headers":[],"relativePath":"02-算法岗-AIGC生成式/01-扩散模型Diffusion.md","filePath":"02-算法岗-AIGC生成式/01-扩散模型Diffusion.md","lastUpdated":1786806808000}'),n={name:"02-算法岗-AIGC生成式/01-扩散模型Diffusion.md"};function l(s,t,r,p,h,u){return e(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="🌫️-01-·-扩散模型-diffusion-⭐-必考" tabindex="-1">🌫️ 01 · 扩散模型 Diffusion（⭐ 必考） <a class="header-anchor" href="#🌫️-01-·-扩散模型-diffusion-⭐-必考" aria-label="Permalink to &quot;🌫️ 01 · 扩散模型 Diffusion（⭐ 必考）&quot;">​</a></h1><blockquote><p>文生图（Stable Diffusion/Midjourney）、视频生成（Sora）的底层。核心思想优雅，面试常让推导。</p></blockquote><hr><h2 id="一、第一性原理" tabindex="-1">一、第一性原理 <a class="header-anchor" href="#一、第一性原理" aria-label="Permalink to &quot;一、第一性原理&quot;">​</a></h2><p><strong>核心问题</strong>：如何从随机高斯噪声 $x_T \\sim \\mathcal{N}(0,I)$ 生成真实数据 $x_0$？</p><p><strong>思路</strong>：定义两个过程——</p><ul><li><strong>前向过程（加噪）</strong>：逐步往数据加高斯噪声，T 步后变成纯噪声。</li><li><strong>反向过程（去噪）</strong>：训练神经网络预测「加的噪声」，逐步去噪还原数据。</li></ul><hr><h2 id="二、前向过程-固定、无参数" tabindex="-1">二、前向过程（固定、无参数） <a class="header-anchor" href="#二、前向过程-固定、无参数" aria-label="Permalink to &quot;二、前向过程（固定、无参数）&quot;">​</a></h2><p>$$q(x_t|x_{t-1}) = \\mathcal{N}(x_t; \\sqrt{1-\\beta_t}x_{t-1}, \\beta_t I)$$</p><p>$\\beta_t$ 是预设的方差 schedule。重要性质：<strong>任意 $x_t$ 可由 $x_0$ 一步采样</strong>（重参数化）：</p><p>$$x_t = \\sqrt{\\bar\\alpha_t},x_0 + \\sqrt{1-\\bar\\alpha_t},\\epsilon,\\quad \\epsilon\\sim\\mathcal{N}(0,I)$$</p><p>$\\alpha_t = 1-\\beta_t,\\ \\bar\\alpha_t = \\prod_{s=1}^t \\alpha_s$。</p><hr><h2 id="三、反向过程-学习去噪" tabindex="-1">三、反向过程（学习去噪） <a class="header-anchor" href="#三、反向过程-学习去噪" aria-label="Permalink to &quot;三、反向过程（学习去噪）&quot;">​</a></h2><p>训练网络 $\\epsilon_\\theta(x_t, t)$ 预测加入的噪声 $\\epsilon$。损失极简：</p><p>$$\\mathcal{L}<em>{simple} = \\mathbb{E}</em>{t,x_0,\\epsilon}\\left[|\\epsilon - \\epsilon_\\theta(x_t,t)|^2\\right]$$</p><p><strong>采样</strong>：从 $x_T\\sim\\mathcal{N}(0,I)$ 出发，反复用网络预测噪声并更新（DDIM/DDPM 采样器），T 步后得到 $x_0$。</p><hr><h2 id="四、条件生成-文生图的关键" tabindex="-1">四、条件生成（文生图的关键） <a class="header-anchor" href="#四、条件生成-文生图的关键" aria-label="Permalink to &quot;四、条件生成（文生图的关键）&quot;">​</a></h2><p>在噪声预测时额外输入条件 $c$（文本 embedding）：</p><p>$$\\epsilon_\\theta(x_t, t, c)$$</p><ul><li><strong>Classifier-Free Guidance（CFG）</strong>：同时训「有条件」和「无条件」模型，推理时插值放大条件信号：</li></ul><p>$$\\tilde\\epsilon = \\epsilon_{uncond} + w,(\\epsilon_{cond} - \\epsilon_{uncond})$$</p><p>$w$ 是引导强度，越大越贴合提示词但多样性降。</p><hr><h2 id="五、latent-diffusion-stable-diffusion-的核心" tabindex="-1">五、Latent Diffusion（Stable Diffusion 的核心） <a class="header-anchor" href="#五、latent-diffusion-stable-diffusion-的核心" aria-label="Permalink to &quot;五、Latent Diffusion（Stable Diffusion 的核心）&quot;">​</a></h2><p>直接在<strong>压缩的潜空间</strong>（VAE 编码后的 latent）上做扩散，而非像素空间：</p><ul><li>先用 VAE 把图像压到低维 latent</li><li>在 latent 上跑 U-Net 去噪</li><li>最后 VAE 解码回图像</li><li><strong>好处</strong>：省算力、质量好；文本条件通过 Cross-Attention 注入 U-Net</li></ul><hr><h2 id="六、加速采样" tabindex="-1">六、加速采样 <a class="header-anchor" href="#六、加速采样" aria-label="Permalink to &quot;六、加速采样&quot;">​</a></h2><ul><li><strong>DDIM</strong>：确定性、少步采样（50→20 步）</li><li><strong>Consistency Models / LCM</strong>：一步/少步生成</li><li><strong>Rectified Flow</strong>：把扩散看成直线流，简化路径</li></ul><hr><h2 id="七、高频追问" tabindex="-1">七、高频追问 <a class="header-anchor" href="#七、高频追问" aria-label="Permalink to &quot;七、高频追问&quot;">​</a></h2><p><strong>Q1：Diffusion 相比 GAN 好在哪？</strong></p><blockquote><p>训练稳定（单纯回归噪声，无对抗博弈）、模式覆盖好（少 mode collapse）、质量高。GAN 训练易崩、易模式崩塌。</p></blockquote><p><strong>Q2：为什么 Latent Diffusion 不用像素空间？</strong></p><blockquote><p>像素空间计算量巨大；latent 空间维度低一个量级，速度和显存大幅优化，质量几乎无损。</p></blockquote><p><strong>Q3：CFG 的 w 太大有什么问题？</strong></p><blockquote><p>过饱和、伪影、多样性骤降、可能偏离真实；太小则忽略提示词。需调参。</p></blockquote><hr><p>➡️ 下一步：<a href="./02-GAN与VAE">02-GAN与VAE</a></p>',42)])])}const d=a(n,[["render",l]]);export{_ as __pageData,d as default};
